  function collections(){const pick=category=>app.products.find(item=>item.category===category),chapters=[{index:'01',title:'The Long Line',copy:'Protective volumes shaped in French wool.',product:pick('coats'),href:'pages/shop/clothing/coats.html'},{index:'02',title:'Objects in Hand',copy:'Leather forms balanced between structure and ease.',product:pick('bags'),href:'pages/shop/accessories/bags.html'},{index:'03',title:'Light at the Neck',copy:'Lyon silk carrying colour through movement.',product:pick('scarves'),href:'pages/shop/accessories/scarves.html'},{index:'04',title:'A Final Gesture',copy:'Small architectural forms in enamel and gold.',product:pick('jewellery'),href:'pages/shop/accessories/jewellery.html'}].filter(chapter=>chapter.product);const used=new Set(chapters.map(x=>x.product.id)),remaining=app.products.filter(p=>!used.has(p.id));return `<section class="collections-manifesto"><nav class="breadcrumb" aria-label="Breadcrumb"><ol><li><a href="${link('index.html')}">Home</a></li><li><span aria-current="page">Collections</span></li></ol></nav><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p><span class="collections-season">AUTUMN / WINTER · PARIS 2026</span></section><section class="collection-chapters">${chapters.map((chapter,index)=>`<a class="collection-chapter${index%2?' reverse':''}" href="${link(chapter.href)}"><div class="collection-chapter-copy"><span>${chapter.index}</span><p class="eyebrow">COLLECTION CHAPTER</p><h2>${chapter.title}</h2><p>${chapter.copy}</p><strong>Discover the chapter →</strong></div><div class="collection-chapter-media"><img src="${R}images/${esc(chapter.product.image)}" alt="${esc(chapter.product.name)}"></div></a>`).join('')}</section><section class="section collection-complete"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">THE COMPLETE WARDROBE</p><h2>Continue through the edit.</h2></div><a class="button wine" href="${link('pages/shop.html')}">Shop all</a></div><div class="product-grid">${remaining.map(product).join('')}</div></div></section>`}
  function shop(){return `<nav class="shop-text-nav" aria-label="Shop categories"><span>Explore the Maison</span><a href="${link('pages/shop/clothing/coats.html')}">Coats</a><a href="${link('pages/shop/accessories/bags.html')}">Bags</a><a href="${link('pages/shop/accessories/scarves.html')}">Silk</a><a href="${link('pages/shop/accessories/jewellery.html')}">Jewellery</a></nav><section class="shop-catalogue section"><div class="wrap"><div class="catalog-tools"><span>${app.products.length} editions</span>${catalogueStatus()}</div>${app.products.length?`<div class="product-grid catalog-grid shop-grid">${app.products.map(product).join('')}</div>`:`<div class="catalogue-empty"><p class="eyebrow">THE MAISON CATALOGUE</p><h2>The next edit is being prepared.</h2><p>There are no published editions at this moment. Please return shortly.</p></div>`}</div></section>`}
  function catalogueTools(products,filters=true){return `<div class="catalog-tools"><span>${products.length} editions</span>${catalogueStatus()}${filters?'<div class="filters"><button class="filter active" data-filter="all">All</button><button class="filter" data-filter="coats">Coats</button><button class="filter" data-filter="bags">Bags</button><button class="filter" data-filter="scarves">Silk</button><button class="filter" data-filter="jewellery">Jewellery</button></div>':''}</div>`}
  function catalogue(){
    const coats=app.products.filter(p=>p.category==='coats'),accessories=app.products.filter(p=>p.category!=='coats'),products=page==='clothing'?coats:page==='accessories'?accessories:app.products.filter(p=>p.category===page);
    if(!products.length)return pageHead()+`<section class="section catalogue-empty"><div class="wrap">${catalogueTools(products,false)}<p class="eyebrow">THE MAISON CATALOGUE</p><h2>No editions are currently published in this chapter.</h2><p>Return to the complete edit or contact Client Care for availability.</p><a class="button wine" href="${link('pages/shop.html')}">Return to shop</a></div></section>`;
    if(page==='clothing'){const [lead,...rest]=products;return pageHead()+`<section class="clothing-feature"><a href="${productLink(lead)}"><img src="${R}images/${lead.image}" alt="${lead.name}"></a><div><p class="eyebrow">THE DEFINING SILHOUETTE</p><h2>${lead.name}</h2><p>${lead.note}</p><a class="button wine" href="${productLink(lead)}">Discover the coat</a></div></section><section class="section clothing-index"><div class="wrap">${catalogueTools(products,false)}<div class="product-grid clothing-grid">${rest.map(product).join('')}</div></div></section>`}
    if(page==='accessories'){const groups=[['bags','Leather objects'],['scarves','Silk studies'],['jewellery','Sculptural gestures']];return pageHead()+`<section class="accessory-chapters">${groups.map(([category,title],index)=>{const items=products.filter(p=>p.category===category);return `<section class="accessory-chapter"><header><span>0${index+1}</span><p class="eyebrow">${category}</p><h2>${title}</h2><a href="${link(`pages/shop/accessories/${category}.html`)}">View chapter →</a></header><div class="product-grid">${items.map(product).join('')}</div></section>`}).join('')}</section>`}
    if(page==='coats')return pageHead()+`<section class="section coats-gallery"><div class="wrap">${catalogueTools(products,false)}<div class="coats-vertical">${products.map((p,index)=>`<article><a href="${productLink(p)}"><img src="${R}images/${p.image}" alt="${p.name}"></a><span>0${index+1}</span><div><p class="eyebrow">${p.reference}</p><h2><a href="${productLink(p)}">${p.name}</a></h2><p>${p.note}</p><strong>${fmt(p.price)}</strong></div></article>`).join('')}</div></div></section>`;
    if(page==='bags')return pageHead()+`<section class="section bags-room"><div class="wrap">${catalogueTools(products,false)}<div class="product-grid bags-grid">${products.map(product).join('')}</div></div></section>`;
    if(page==='scarves')return pageHead()+`<section class="section silk-library"><div class="wrap">${catalogueTools(products,false)}<div class="product-grid silk-grid">${products.map(product).join('')}</div></div></section>`;
    if(page==='jewellery')return pageHead()+`<section class="section jewel-salon"><div class="wrap">${catalogueTools(products,false)}<p class="jewel-intro">Five objects arranged as points of light.</p><div class="product-grid jewel-grid">${products.map(product).join('')}</div></div></section>`;
    return pageHead()+`<section class="section"><div class="wrap">${catalogueTools(products)}<div class="product-grid catalog-grid">${products.map(product).join('')}</div></div></section>`
  }
  function journal(){const posts=(app.journalPosts||[]).filter(item=>item.published!==false).sort((a,b)=>Number(b.featured)-Number(a.featured)||Number(a.sort_order)-Number(b.sort_order)),lead=posts.find(item=>item.featured)||posts[0],stories=posts.filter(item=>item!==lead);const action=post=>post.link_path?`<a href="${link(post.link_path)}">Read the story →</a>`:'';return `<section class="journal-masthead" data-dynamic-region="journal"><nav class="breadcrumb" aria-label="Breadcrumb"><ol><li><a href="${link('index.html')}">Home</a></li><li><span aria-current="page">Journal</span></li></ol></nav><div><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1>${journalStatus()}</div><p>${c.intro}</p><span>${String(posts.length).padStart(2,'0')} STORIES · PARIS</span></section>${lead?`<section class="journal-lead"><img src="${R}images/${esc(lead.image)}" alt="${esc(lead.alt_text)}"><div class="journal-lead-copy"><p class="eyebrow">${esc(lead.eyebrow)}</p><h2>${esc(lead.title)}</h2><p>${esc(lead.summary)} ${esc(lead.body||'')}</p>${lead.link_path?`<a class="button wine" href="${link(lead.link_path)}">Enter the story</a>`:''}</div></section>`:''}<section class="section"><div class="wrap journal-search-block"><div><p class="eyebrow">THE JOURNAL INDEX</p><h2>Stories of craft, <em>material and memory.</em></h2><p class="intro">Search the ÉLANE Journal by silhouette, material, savoir-faire or archive. New database stories enter this index automatically.</p></div><div><label class="search-label" for="journal-search">Search stories</label><input id="journal-search" class="search-input" placeholder="Try ‘silk’, ‘archive’ or ‘leather’"><p class="journal-search-note">Explore atelier notes, material studies and seasonal perspectives from Paris.</p></div></div><div class="wrap journal-index">${stories.map((post,index)=>`<article class="journal-entry${index>1?' journal-entry-compact':''}" data-search="${esc(`${post.keywords||''} ${post.title} ${post.summary}`)}"><img loading="lazy" src="${R}images/${esc(post.image)}" alt="${esc(post.alt_text)}"><div><p class="eyebrow">${esc(post.eyebrow)}</p><h3>${esc(post.title)}</h3><p>${esc(post.summary)} ${esc(post.body||'')}</p>${action(post)}</div></article>`).join('')}<p class="journal-empty"${stories.length?' hidden':''}>No journal story matches that search. Try a material, object or craft.</p></div></section>`}
  function article(){const isAtelier=page==='atelier';if(!isAtelier)return pageHead()+`<section class="material-film section"><div class="wrap material-film-grid"><div><p class="eyebrow">MATERIAL FILM · SILK</p><h2>Light changes what the hand already knows.</h2><p>Our wool has weight without stiffness; our silk carries light with a muted sheen; our leather becomes more individual with time.</p><a class="button wine" href="${link('pages/journal/materials-lab.html')}">Open the interactive lab</a></div><video autoplay muted loop playsinline preload="metadata"><source src="${R}video/silk-texture.mp4" type="video/mp4"></video></div></section>`;return pageHead()+`<section class="atelier-process section"><div class="wrap"><ol class="process-steps"><li><span>01</span><h2>Draw the line</h2><p>A silhouette begins as proportion, not decoration.</p></li><li><span>02</span><h2>Test in motion</h2><p>Before a garment is named, it is walked in and revised.</p></li><li><span>03</span><h2>Remove the excess</h2><p>Fewer decisions let the essential ones become exact.</p></li></ol><a class="button wine" href="${link('pages/collections.html')}">See the collection</a></div></section>`}
  function maison(){return pageHead()+`<section class="maison-statement section"><div class="wrap"><p class="maison-index">1932 — 2026</p><p class="quote">A house is not made by repeating the past. It is made by knowing what deserves to continue.</p><div class="maison-links"><a href="${link('pages/maison/heritage.html')}"><span>01</span><strong>Explore the heritage</strong><em>Four generations of craft and invention</em></a><a href="${link('pages/maison/codes.html')}"><span>02</span><strong>Read the house codes</strong><em>Line, proportion, light and time</em></a><a href="${link('pages/campaign/nocturne-2026.html')}"><span>03</span><strong>Watch Nocturne 2026</strong><em>A campaign film in three movements</em></a><a href="${link('pages/maison/salon.html')}"><span>04</span><strong>Enter 18 Rue du Bac</strong><em>Explore the private Paris salon</em></a><a href="${link('pages/maison/making.html')}"><span>05</span><strong>Follow the making</strong><em>From first pattern to final form</em></a><a href="${link('pages/shows.html')}"><span>06</span><strong>Watch the shows</strong><em>The Maison expressed through movement</em></a></div></div></section>`}

  function maisonCodes(){const items=[
    {n:'01',name:'Line',note:'A single uninterrupted gesture gives the body direction without constraint.',image:'codes-line.png',alt:'Model in a long black coat defined by one ivory line',tone:'line'},
    {n:'02',name:'Proportion',note:'Volume is placed with purpose: enough to hold presence, never to overwhelm it.',image:'codes-proportion.png',alt:'Model in a sculptural ivory dress inside a circular gallery',tone:'proportion'},
    {n:'03',name:'Light',note:'Surface is chosen for the way it receives daylight, movement and the passing hour.',image:'codes-light.png',alt:'Ivory organza silhouette filtered through translucent curtains',tone:'light'},
    {n:'04',name:'Time',note:'A piece is complete only when it can gather memory and remain itself.',image:'codes-time.png',alt:'Woman in an oxblood gown beside an aged mirror',tone:'time'}
  ];return `<section class="codes-opening"><div class="wrap">${breadcrumb()}<p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p><span class="codes-scroll-cue">Scroll to read the four codes <i aria-hidden="true"></i></span></div></section><section class="codes-experience" data-codes><div class="codes-sticky" tabindex="-1"><div class="codes-light-field" aria-hidden="true"></div><div class="codes-scenes">${items.map((item,index)=>`<article class="codes-scene${index===0?' is-active':''}" data-code-scene data-tone="${item.tone}" aria-hidden="${index!==0}"><div class="codes-image"><img ${index?'loading="lazy"':'fetchpriority="high"'} width="1400" height="1120" src="${R}images/experiences/${item.image}" alt="${item.alt}"></div><div class="codes-copy"><span>${item.n} / 04</span><h2>${item.name}</h2><p>${item.note}</p></div></article>`).join('')}</div><div class="codes-chrome"><p>ÉLANE · House vocabulary</p><nav aria-label="Choose a design code">${items.map((item,index)=>`<button type="button" data-code-index="${index}" class="${index===0?'is-active':''}" aria-label="Show code ${item.n}: ${item.name}" aria-pressed="${index===0}"><span>${item.n}</span><em>${item.name}</em></button>`).join('')}</nav><div class="codes-meter" aria-hidden="true"><i></i></div></div></div></section><section class="codes-coda"><div><p class="eyebrow">A LIVING LANGUAGE</p><h2>Recognisable by feeling,<br>never by repetition.</h2></div><p>These codes are not fixed motifs. They are decisions: where a seam begins, how a volume settles, what a surface reveals and how an object changes through use.</p><a class="text-link" href="${link('pages/maison/making.html')}">See the codes being made →</a></section>`}

  function nocturne(){return `<section class="nocturne-hero dark"><video autoplay muted loop playsinline preload="metadata"><source src="${R}video/nocturne-silk-pexels.mp4" type="video/mp4"></video><div class="nocturne-shade"></div><div class="nocturne-title"><p>${c.eyebrow}</p><h1><span>Nocturne</span><em>Paris · 2026</em></h1><p>${c.intro}</p></div><div class="nocturne-edge"><span>Campaign film</span><button type="button" data-video-control aria-label="Pause film">Pause film</button></div><span class="nocturne-aperture" aria-hidden="true"></span></section><section class="nocturne-story" data-nocturne><div class="nocturne-sticky"><header><span>NOCTURNE / THREE MOVEMENTS</span><strong data-nocturne-count>02 — AFTERLIGHT</strong></header><div class="nocturne-frames"><article class="nocturne-frame is-active" data-nocturne-frame><img loading="lazy" width="1680" height="945" src="${R}images/experiences/nocturne-courtyard.png" alt="Model crossing a rain-lit Paris courtyard at night"><div><small>Movement II</small><h2>Afterlight</h2><p>The city becomes a mirror. A black line moves through blue stone and amber rain.</p></div></article><article class="nocturne-frame" data-nocturne-frame aria-hidden="true"><img loading="lazy" width="1680" height="945" src="${R}images/experiences/nocturne-silk-still.png" alt="Black-gloved hand gathering deep oxblood silk"><div><small>Movement III</small><h2>Trace</h2><p>What remains is colour in motion: oxblood silk, held for a moment before darkness returns.</p></div></article></div><nav aria-label="Campaign movements"><button class="is-active" data-nocturne-index="0" aria-label="Show movement two" aria-pressed="true">II</button><button data-nocturne-index="1" aria-label="Show movement three" aria-pressed="false">III</button></nav><span class="nocturne-progress" aria-hidden="true"><i></i></span></div></section><section class="nocturne-coda dark"><p class="eyebrow">NOCTURNE · 2026</p><blockquote>Night does not conceal the line.<br>It teaches the eye to find it.</blockquote><a class="button" href="${link('pages/collections.html')}">Discover the collection</a></section>`}

  function salon(){const notes=[
    {title:'The fitting room',label:'01 · Proportion',copy:'A private fitting begins with how a piece should feel in motion. Pins and chalk refine the line without rushing the decision.'},
    {title:'The material library',label:'02 · Touch',copy:'Seasonal wools, silks and leathers are seen in daylight and compared by hand before a personal edit is formed.'},
    {title:'The objects table',label:'03 · Detail',copy:'Bags, scarves and jewellery are placed beside a silhouette so that each final gesture can be understood in context.'}
  ];return `<section class="salon-opening"><div class="salon-room" data-salon-room><img fetchpriority="high" width="1680" height="945" src="${R}images/experiences/salon-hero.png" alt="Sunlit private ÉLANE salon at 18 Rue du Bac in Paris"><span class="salon-daylight" aria-hidden="true"></span><div class="salon-heading"><p>${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p></div>${notes.map((note,index)=>`<button type="button" class="salon-hotspot${index===0?' is-active':''}" data-salon-hotspot="${index}" style="--hot-x:${[22,57,76][index]}%;--hot-y:${[62,42,67][index]}%" aria-label="Open ${note.title}" aria-pressed="${index===0}"><i></i><span>${String(index+1).padStart(2,'0')}</span></button>`).join('')}<aside class="salon-note" aria-live="polite"><button class="salon-note-close" type="button" aria-label="Minimise room note">×</button>${notes.map((note,index)=>`<article class="${index===0?'is-active':''}" data-salon-note aria-hidden="${index!==0}"><small>${note.label}</small><h2>${note.title}</h2><p>${note.copy}</p></article>`).join('')}<span>Choose a point in the room</span></aside><div class="salon-coordinates"><span>48.8532° N</span><span>2.3269° E</span></div></div></section><section class="salon-ritual"><div class="salon-ritual-copy"><p class="eyebrow">THE APPOINTMENT RITUAL</p><h2>A room arranged<br>around your pace.</h2><p>Appointments are held one-to-one. Your adviser prepares a concise selection in advance, then leaves space to compare proportion, material and movement in natural light.</p><dl><div><dt>Place</dt><dd>18 Rue du Bac, Paris 7e</dd></div><div><dt>Hours</dt><dd>Tuesday—Saturday, 10:00—18:00</dd></div><div><dt>Language</dt><dd>French · English · Cantonese</dd></div></dl><a class="button wine" href="${link('pages/services/appointment.html')}">Request a private appointment</a></div><figure><img loading="lazy" width="1536" height="1024" src="${R}images/experiences/salon-appointment.png" alt="Fabrics and dressmaking tools prepared for a private appointment"><figcaption>Materials are prepared for each conversation.</figcaption></figure></section>`}

  function making(){const steps=[
    {n:'01',title:'The pattern',tag:'Measure before gesture',copy:'The first line is drawn on paper. Balance is tested flat before a single cut is made.',kind:'image',src:'making-pattern.png',alt:'Artisan aligning a paper pattern over black wool'},
    {n:'02',title:'The assembly',tag:'Structure without weight',copy:'Panels are basted by hand, joined, released and joined again until the piece holds its intended movement.',kind:'diagram'},
    {n:'03',title:'The finish',tag:'What the hand leaves behind',copy:'Edges, beads and inner seams are completed at the pace required by the material, never by the clock.',kind:'image',src:'making-finishing.png',alt:'Artisan sewing tiny garnet beads onto black silk'},
    {n:'04',title:'The form',tag:'The final adjustment',copy:'On the form, the hem is balanced and every line is viewed from distance. Only then does the piece leave the atelier.',kind:'image',src:'making-form.png',alt:'Finished black ÉLANE coat adjusted on a dress form'}
  ];return `<section class="making-hero"><div class="making-hero-copy"><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p><div><span>One piece</span><span>Four stages</span><span>Thirty-seven hours</span></div></div><div class="making-film"><video autoplay muted loop playsinline preload="metadata"><source src="${R}video/making-sewing-pexels.mp4" type="video/mp4"></video><button type="button" data-video-control aria-label="Pause film">Pause film</button><span>Atelier study · 01</span></div></section><section class="making-process" data-making><div class="making-rail"><span>01</span><i><b></b></i><span>04</span></div><div class="making-worktop"><div class="making-media">${steps.map((step,index)=>step.kind==='image'?`<figure class="${index===0?'is-active':''}" data-making-media aria-hidden="${index!==0}"><img loading="lazy" width="1450" height="1088" src="${R}images/experiences/${step.src}" alt="${step.alt}"><figcaption>${step.n} · ${step.tag}</figcaption></figure>`:`<figure class="making-diagram" data-making-media aria-hidden="true"><div aria-hidden="true"><i></i><i></i><i></i><i></i><b></b></div><figcaption>${step.n} · ${step.tag}</figcaption></figure>`).join('')}</div><p data-making-status>01 / 04 · PATTERN</p></div><div class="making-steps">${steps.map((step,index)=>`<article class="${index===0?'is-active':''}" data-making-step><span>${step.n}</span><small>${step.tag}</small><h2>${step.title}</h2><p>${step.copy}</p></article>`).join('')}</div></section><section class="making-coda"><p class="eyebrow">TIME, RECORDED BY HAND</p><h2>37 hours.<br>One continuous line.</h2><div>${steps.map(step=>`<article><span>${step.n}</span><strong>${step.title}</strong><p>${step.tag}</p></article>`).join('')}</div><a class="text-link" href="${link('pages/maison/codes.html')}">Return to the house codes →</a></section>`}
  function services(){return pageHead()+`<section class="section services-orbit"><div class="wrap"><div class="service-orbit-center"><span>É</span><p>Client care follows the complete life of an object.</p></div><div class="service-orbit-grid"><article><span>01</span><h3>Private appointment</h3><p>Meet the collection at your pace, with a dedicated stylist.</p><a class="button wine" href="${link('pages/services/appointment.html')}">Book a time</a></article><article><span>02</span><h3>Delivery & care</h3><p>Transparent delivery, thoughtful packaging and lasting support.</p><a class="button wine" href="${link('pages/services/shipping.html')}">Learn more</a></article><article><span>03</span><h3>Client account</h3><p>Keep your orders, saved pieces and notes in one place.</p><a class="button wine" href="${link('pages/account/sign-in.html')}">Sign in</a></article></div></div></section>`}
  function shows(){return `<section class="show-wheel-story" style="--show-panels:4" aria-label="ÉLANE fashion show chapters"><div class="show-wheel-sticky" tabindex="0" aria-label="Scroll to move through the fashion show"><div class="show-wheel-viewport"><div class="show-wheel-track"><article class="show-wheel-panel show-wheel-film is-active" data-show-chapter="01"><video autoplay muted loop playsinline preload="metadata"><source src="${R}video/runway-red-look.mp4" type="video/mp4"></video><div class="shows-hero-shade"></div><div class="show-wheel-copy"><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p><span class="show-wheel-cue">Scroll to discover <i>→</i></span></div><button class="film-control" data-video-control>Pause film</button></article><article class="show-wheel-panel show-wheel-collection" data-show-chapter="02"><img class="show-scene-media" src="${R}images/editorial/show-scene-afterlight.png" alt="Black sculptural coat crossing a shadowed Paris runway"><span class="show-wheel-ghost">26</span><div class="show-wheel-copy"><p class="eyebrow">AUTUMN / WINTER 2026 · PARIS</p><h2>The architecture<br>of <em>afterlight.</em></h2><p>Eighteen silhouettes move between shadow, stone and oxblood light.</p><a class="button light" href="${link('pages/shows/autumn-winter-2026.html')}">Enter the runway</a></div><span class="show-wheel-side">THE COLLECTION · 18 LOOKS</span></article><article class="show-wheel-panel show-wheel-art" data-show-chapter="03"><img class="show-scene-media" src="${R}images/editorial/show-scene-art-space.png" alt="Ivory sculptural couture staged inside an oxblood art gallery"><span class="show-wheel-orbit" aria-hidden="true"></span><div class="show-wheel-copy"><p class="eyebrow">ARTISTIC LOOKS · STUDY 01</p><h2>Fashion as<br><em>image and space.</em></h2><p>Three sculptural studies test how a silhouette changes the room around it.</p><a class="button light" href="${link('pages/shows/artistic-looks.html')}">Explore the studies</a></div><strong class="show-wheel-mark">É</strong></article><article class="show-wheel-panel show-wheel-finale" data-show-chapter="04"><img class="show-scene-media" src="${R}images/editorial/show-scene-finale.png" alt="Three couture silhouettes walking into the morning light of a Paris salon"><div class="show-wheel-copy"><p class="eyebrow">ÉLANE · PARIS</p><h2>The show ends.<br>The gesture <em>continues.</em></h2><p>Return to the collection, enter the atelier or move into the Maison archive.</p><div class="show-wheel-actions"><a class="button wine" href="${link('pages/collections.html')}">View collections</a><a class="text-link" href="${link('pages/maison/heritage.html')}">Explore the heritage →</a></div></div><span class="show-wheel-signature">ÉLANE</span></article></div></div><div class="show-wheel-ui"><span class="show-wheel-current">01</span><div class="show-wheel-progress" aria-hidden="true"><i></i></div><nav aria-label="Show chapters"><button class="is-active" data-show-index="0" aria-current="step">01</button><button data-show-index="1">02</button><button data-show-index="2">03</button><button data-show-index="3">04</button></nav><span class="show-wheel-total">04</span></div></div></section>`}
  function showDetail(){return `<section class="runway-title"><div><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p></div><span class="runway-number">18</span></section><section class="runway-backstage"><video autoplay muted loop playsinline preload="metadata"><source src="${R}video/runway-backstage.mp4" type="video/mp4"></video><div class="runway-caption"><p class="eyebrow">BEFORE THE LIGHTS</p><h2>Backstage is where precision becomes instinct.</h2><button class="button light" data-video-control>Pause film</button></div></section><section class="runway-lookbook section dark"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">SELECTED LOOKS</p><h2>Move through the collection</h2></div><div class="rail-controls"><button data-rail="-1" aria-label="Previous look">←</button><button data-rail="1" aria-label="Next look">→</button></div></div></div><div class="look-rail" tabindex="0"><figure><img src="${R}images/editorial/runway-look-01.png" alt="Black and oxblood sculptural couture gown on the runway"><figcaption><span>Look 01</span><strong>Folded shadow</strong></figcaption></figure><figure class="look-quote"><blockquote>“Volume only matters when it changes with the body.”</blockquote><cite>Atelier note 26.04</cite></figure><figure class="wide"><img src="${R}images/editorial/runway-finale.png" alt="Three couture silhouettes walking toward a luminous arch"><figcaption><span>Finale</span><strong>Into afterlight</strong></figcaption></figure></div></section><section class="runway-credits"><span>Direction · ÉLANE Studio</span><span>Paris · 2026</span><a href="${link('pages/shows/artistic-looks.html')}">Continue to Artistic Looks →</a></section>`}
  function artisticLooks(){return pageHead()+`<section class="art-gallery" aria-label="Artistic fashion looks"><button class="art-card art-card-one" data-lightbox><img src="${R}images/editorial/art-look-ivory.png" alt="Ivory cape in a circular gallery"><span><b>01</b> The quiet curve</span></button><div class="art-gallery-copy"><p>Click each image to enter the full frame.</p><i></i></div><button class="art-card art-card-two" data-lightbox><img src="${R}images/editorial/art-look-champagne.png" alt="Champagne silk dress beside a stone staircase"><span><b>02</b> Light held in folds</span></button><button class="art-card art-card-three" data-lightbox><img src="${R}images/editorial/art-look-oxblood.png" alt="Oxblood tailored coat in a lacquered room"><span><b>03</b> A room in red</span></button></section><section class="art-closing dark"><p class="eyebrow">ART IS A WAY OF TESTING THE SILHOUETTE</p><h2>Not every study becomes a garment.<br>Every study changes the next one.</h2></section>`}
  function heritage(){const chapters=[
    {year:'1932',label:'Since 1932 · The first room',title:'Enduring heritage begins with one exact line.',copy:'Élise Laurent opens a small atelier at 18 Rue du Bac. Her first six coats favour precise shoulders, useful pockets and an uncommon freedom of movement.',image:'heritage-founder-elise.png',alt:'Élise Laurent beside her first black wool coat in the Paris atelier',cover:true},
    {year:'1937',label:'An enduring silhouette',title:'The Column coat enters the vocabulary.',copy:'A long black coat with a softened shoulder and concealed fastening establishes the quiet, architectural silhouette that will define ÉLANE.',image:'heritage-1932.png',alt:'Élise Laurent drawing a coat pattern in her first Paris atelier'},
    {year:'1948',label:'The salon returns',title:'Craft is rebuilt through conversation.',copy:'After years of scarcity, the complete fitting rooms reopen. Clients, cutters and fitters shape each garment together, restoring the human rhythm of the Maison.',image:'heritage-atelier-1948.png',alt:'ÉLANE artisans reopening the Paris atelier in 1948'},
    {year:'1964',label:'Architecture in cloth',title:'Claire Laurent changes the space around the body.',copy:'Trained in architecture, the founder’s daughter introduces curved seams, suspended volumes and a new salon in which cloth, movement and space are studied together.',image:'heritage-salon-1964.png',alt:'ÉLANE fitters adjusting an ivory coat in the 1964 Paris salon'},
    {year:'1976',label:'The first leather object',title:'A coat seam becomes the Arc bag.',copy:'The Maison translates a familiar curved construction into calfskin. Fashion and leatherwork begin a dialogue that continues across every collection.',image:'heritage-1964.png',alt:'A historical ÉLANE fitting in a Paris salon'},
    {year:'1987',label:'Silk from Lyon',title:'Colour is given its own movement.',copy:'ÉLANE works with a family weaving house in Lyon on its first carré, layering mineral shades so that each line retains depth and luminosity.',image:'heritage-silk-1987.png',alt:'Artisans printing an ÉLANE silk carré in Lyon in 1987'},
    {year:'1998',label:'The working archive',title:'Memory becomes a design instrument.',copy:'Thousands of drawings, patterns and fitting notes are catalogued—not to preserve the past untouched, but to help the next generation understand why a proportion works.',image:'heritage-archive-1998.png',alt:'ÉLANE archivists studying a historical pattern portfolio in 1998'},
    {year:'2008',label:'Objects of permanence',title:'Jewellery enters the Maison.',copy:'Small architectural forms in brushed gold, enamel and onyx extend ÉLANE’s language from the silhouette to objects held close to the body.',image:'heritage-jewellery-2008.png',alt:'An ÉLANE jeweller crafting a gold and onyx piece in 2008'},
    {year:'2016',label:'The atelier in motion',title:'Film reveals what a still image cannot.',copy:'Moving image becomes part of the house language, recording how wool, silk and leather change through gesture, light and time.',image:'heritage-film-2016.png',alt:'ÉLANE filming a black coat and oxblood silk in a Paris studio in 2016'},
    {year:'2026',label:'A legacy in motion',title:'The past remains useful because it keeps moving.',copy:'ÉLANE brings tailoring, leatherwork, jewellery, film and digital interaction into one contemporary French Maison.',image:'heritage-maison-2026.png',alt:'The contemporary ÉLANE atelier and collection in Paris in 2026',final:true}
  ];const pages=chapters.map((chapter,index)=>`<article class="heritage-book-page has-image${chapter.cover?' cover-page':''}${chapter.final?' final-page':''}${index%2?' image-right':''}" data-book-year="${chapter.year}" aria-label="${chapter.year}: ${chapter.title}"><div class="heritage-book-media"><img src="${R}images/editorial/${chapter.image}" alt="${chapter.alt}"></div><div class="heritage-book-copy"><span class="heritage-book-index">${String(index+1).padStart(2,'0')} / ${String(chapters.length).padStart(2,'0')}</span><p class="heritage-kicker">${chapter.label}</p><time>${chapter.year}</time><h2>${chapter.title}</h2><p>${chapter.copy}</p>${chapter.cover?'<span class="heritage-wheel-cue">Scroll to turn the pages ↓</span>':''}${chapter.final?`<div class="heritage-final-actions"><a class="button light" href="${link('pages/shows.html')}">See the Maison today</a><a class="button ghost-light" href="${link('pages/journal/atelier.html')}">Enter the atelier</a></div>`:''}</div><span class="heritage-page-edge" aria-hidden="true"></span></article>`).join('');const indexItems=chapters.map((chapter,index)=>`<button data-book-index="${index}"${index===0?' class="is-active" aria-current="step"':''}><span>${chapter.year}</span><strong>${chapter.label}</strong></button>`).join('');return `<section class="heritage-book heritage-book-entire" style="--book-pages:${chapters.length}" aria-label="ÉLANE history from 1932 to 2026"><div class="heritage-book-sticky" tabindex="0" aria-label="Scroll to move through the history, or use left and right arrow keys"><div class="heritage-book-heading"><p class="eyebrow">ÉLANE · ENDURING HERITAGE</p><span class="heritage-book-instruction">Scroll to turn the pages</span></div><div class="heritage-book-viewport"><div class="heritage-book-track">${pages}</div></div><div class="heritage-book-progress" aria-hidden="true"><i></i></div><div class="heritage-book-dock"><span class="heritage-dock-brand">ÉLANE</span><span class="heritage-current-year" aria-live="polite">1932</span><button class="heritage-menu-toggle" type="button" aria-expanded="false" aria-controls="heritage-index-menu">Years <i aria-hidden="true"></i></button></div><aside class="heritage-index-menu" id="heritage-index-menu" aria-hidden="true"><header><div><p class="eyebrow">ÉLANE ARCHIVES</p><h2>Choose a year</h2></div><button class="heritage-menu-close" type="button" aria-label="Close year index">Close <span aria-hidden="true">×</span></button></header><nav class="heritage-index-grid" aria-label="Heritage years">${indexItems}</nav></aside></div></section>`}
  function materialsLab(){return `<section class="materials-stage"><div class="materials-heading"><p class="eyebrow">${c.eyebrow}</p><h1>${c.title}</h1><p>${c.intro}</p></div><div class="materials-canvas"><img src="${R}images/editorial/materials-lab.png" alt="Abstract arrangement of wool, silk, leather and champagne metal around a polished stone"><button class="material-hotspot wool is-active" data-material="wool" aria-label="Explore black wool"><span>01</span></button><button class="material-hotspot silk" data-material="silk" aria-label="Explore oxblood silk"><span>02</span></button><button class="material-hotspot leather" data-material="leather" aria-label="Explore ivory leather"><span>03</span></button><button class="material-hotspot metal" data-material="metal" aria-label="Explore champagne metal"><span>04</span></button></div><aside class="material-panel" aria-live="polite"><span class="material-index">01 / WOOL</span><h2>Structure without stiffness.</h2><p>Dense French wool is brushed, rested and cut to hold a clean line while remaining responsive to movement.</p><div class="material-meter"><i style="--level:82%"></i></div><small>Touch character · protective · matte · warm</small></aside><p class="materials-instruction">Select a numbered point to reveal the material.</p></section>`}
  function appointment(){return pageHead()+`<section class="section"><div class="wrap split"><div class="split-copy"><h2>Visit the <em>Paris salon.</em></h2><p>45 minutes · 18 Rue du Bac, Paris · Tuesday to Saturday</p><p>A dedicated advisor will prepare a personal selection from the collection. No purchase is expected.</p></div><form id="appointment-form" class="split-copy form-grid"><div class="field"><label for="appointment-name">Name</label><input id="appointment-name" required name="name" autocomplete="name"></div><div class="field"><label for="appointment-email">Email</label><input id="appointment-email" required type="email" name="email" autocomplete="email"></div><div class="field"><label for="appointment-date">Date</label><input id="appointment-date" required type="date" name="date"></div><div class="field"><label for="appointment-time">Time</label><select id="appointment-time" name="time"><option>11:00</option><option>14:00</option><option>17:00</option></select></div><div class="field full"><label for="appointment-note">What would you like to see?</label><textarea id="appointment-note" name="note" rows="3"></textarea></div><div class="field full"><button class="button wine">Request appointment</button><p class="form-status" aria-live="polite"></p></div></form></div></section>`}
  function shipping(){return pageHead()+`<section class="section"><div class="wrap"><ul class="line-list"><li><strong>France & Monaco</strong><span>Complimentary delivery · 1–3 working days</span></li><li><strong>International delivery</strong><span>Rates calculated at checkout · 3–8 working days</span></li><li><strong>Returns</strong><span>14 days, unused and in original condition</span></li><li><strong>Care</strong><span>Material guidance and Maison repair advice with every piece</span></li></ul></div></section><section class="section dark"><div class="wrap"><p class="quote">The longest life is the most beautiful one.</p></div></section>`}
  function account(){const type=page; if(type==='wishlist')return pageHead()+`<section class="section"><div class="wrap"><div class="product-grid saved-grid"></div></div></section>`;if(type==='cart')return pageHead()+`<section class="section"><div class="wrap cart-layout"><div class="cart-list"></div><aside class="summary cart-summary" aria-label="Order summary"></aside></div></section>`;return pageHead()+`<section class="section"><div class="wrap" style="max-width:560px"><form class="form-grid sign-form"><div class="field full"><label for="sign-email">Email address</label><input id="sign-email" required type="email" autocomplete="email"></div><div class="field full"><label for="sign-password">Password</label><input id="sign-password" required type="password" autocomplete="current-password"></div><div class="field full"><button class="button wine">Sign in</button></div></form><p class="intro">This prototype uses a client-side account screen. Products, orders and appointments are managed through the included PHP/MySQL API.</p></div></section>`}
  function checkout(){const items=cart.map(id=>app.products.find(p=>p.id===id)).filter(Boolean),total=items.reduce((sum,p)=>sum+p.price,0);return `<section class="checkout-experience"><aside class="checkout-overview"><nav class="breadcrumb" aria-label="Breadcrumb"><ol><li><a href="${link('index.html')}">Home</a></li><li><a href="${link('pages/account/cart.html')}">Bag</a></li><li><span aria-current="page">Checkout</span></li></ol></nav><div><p class="eyebrow">SECURE CHECKOUT</p><h1>Complete your<br><em>selection.</em></h1><ol class="checkout-steps"><li class="is-complete"><span>01</span>Bag</li><li class="is-current"><span>02</span>Delivery &amp; payment</li><li><span>03</span>Confirmation</li></ol></div><div class="checkout-order"><header><span>Your order</span><strong>${items.length} ${items.length===1?'piece':'pieces'}</strong></header>${items.length?items.map(p=>`<a href="${productLink(p)}"><img src="${R}images/${p.image}" alt="${p.name}"><span><strong>${p.name}</strong><small>${p.colour}</small></span><em>${fmt(p.price)}</em></a>`).join(''):'<p>Your bag is currently empty.</p>'}<footer><span>Total</span><strong>${fmt(total)}</strong></footer><a class="checkout-back" href="${link('pages/account/cart.html')}">← Return to bag</a></div></aside><div class="checkout-details"><header><span>02 / 03</span><p class="eyebrow">DELIVERY &amp; PAYMENT</p><h2>Details for your order</h2><p>Fields marked with an asterisk are required. Complimentary delivery is included.</p></header><form id="checkout-form" class="checkout-form"><section><span>01</span><div><h3>Contact</h3><div class="form-grid"><div class="field"><label for="checkout-first-name">First name *</label><input id="checkout-first-name" required name="first_name" autocomplete="given-name"></div><div class="field"><label for="checkout-last-name">Last name *</label><input id="checkout-last-name" required name="last_name" autocomplete="family-name"></div><div class="field full"><label for="checkout-email">Email *</label><input id="checkout-email" required type="email" name="email" autocomplete="email"></div><div class="field full"><label for="checkout-phone">Phone *</label><input id="checkout-phone" required type="tel" name="phone" autocomplete="tel"></div></div></div></section><section><span>02</span><div><h3>Delivery</h3><div class="form-grid"><div class="field full"><label for="checkout-address">Delivery address *</label><input id="checkout-address" required name="address" autocomplete="street-address"></div><div class="field"><label for="checkout-city">City *</label><input id="checkout-city" required name="city" autocomplete="address-level2"></div><div class="field"><label for="checkout-postcode">Postal code *</label><input id="checkout-postcode" required name="postcode" autocomplete="postal-code"></div></div></div></section><section><span>03</span><div><h3>Payment</h3><p class="checkout-prototype-note">Academic prototype — do not enter real payment details.</p><div class="form-grid"><div class="field full"><label for="checkout-card">Card number *</label><input id="checkout-card" required name="card_number" inputmode="numeric" placeholder="0000 0000 0000 0000"></div><div class="field"><label for="checkout-expiry">Expiry *</label><input id="checkout-expiry" required name="expiry" inputmode="numeric" placeholder="MM / YY"></div><div class="field"><label for="checkout-cvc">Security code *</label><input id="checkout-cvc" required name="cvc" inputmode="numeric" placeholder="CVC"></div></div></div></section><div class="checkout-submit"><button class="button wine" type="submit">Place order · ${fmt(total)}</button><p class="form-status" aria-live="polite"></p><small>By placing the order, you agree to the prototype terms of sale.</small></div></form></div></section>`}
  function detail(){
    const id=Number(document.body.dataset.productId||new URLSearchParams(location.search).get('id'))||1,p=app.products.find(x=>x.id===id)||app.products[0];
    document.title=`${p.name} | ÉLANE`;
    const details=(p.details||[]).map(item=>`<li>${esc(item)}</li>`).join('');
    const clothing=p.category==='coats',categoryLabel=p.category.charAt(0).toUpperCase()+p.category.slice(1),productTrail=[{label:'Home',href:link('index.html')},{label:'Shop',href:link('pages/shop.html')},{label:clothing?'Clothing':'Accessories',href:link(clothing?'pages/shop/clothing.html':'pages/shop/accessories.html')},{label:categoryLabel,href:link(clothing?'pages/shop/clothing/coats.html':`pages/shop/accessories/${p.category}.html`)},{label:p.name}];
    const saved=wish.includes(p.id),stock=Number.isFinite(Number(p.stock))?Number(p.stock):5,available=stock>0;
    return pageHead(productTrail)+`<section class="section product-focus" data-dynamic-region="product-detail"><div class="wrap split product-split"><div class="split-media product-gallery"><img src="${R}images/${esc(p.image)}" alt="${esc(p.name)} in ${esc(p.colour)}"></div><div class="split-copy product-purchase"><p class="eyebrow">${esc(p.category)} · ${esc(p.reference)}</p><h2>${esc(p.name)}</h2><p class="product-colour">${esc(p.colour)}</p><p class="price product-price">${fmt(p.price)}</p><p class="product-live-stock" data-state="${available?'available':'unavailable'}"><i></i>${available?`${stock} pieces available · ${catalogueDataSource==='live'?'Live inventory':'Curated preview'}`:'Unavailable · Contact Client Care'}</p><div class="rule"></div><p class="product-description">${esc(p.description||p.note)}</p><div class="field product-option"><label for="product-colour">Colour</label><select id="product-colour" aria-label="Choose colour"><option>${esc(p.colour)}</option></select></div><div class="product-actions"><button class="icon-action add primary-action" data-id="${p.id}" aria-label="${available?`Add ${esc(p.name)} to bag`:`${esc(p.name)} is unavailable`}"${available?'':' disabled'}>${actionIcon('bag')}<span>${available?'Add to bag':'Unavailable'}</span></button><button class="icon-action save${saved?' is-selected':''}" data-id="${p.id}" aria-pressed="${saved}" aria-label="Save ${esc(p.name)}">${actionIcon('save')}<span>${saved?'Saved':'Save'}</span></button></div><p class="product-service-note">Complimentary delivery · Returns within 14 days · Maison presentation included</p></div></div></section><section id="product-information" class="section product-information"><div class="wrap product-information-grid"><div class="product-information-intro"><p class="eyebrow">PRODUCT INFORMATION</p><h2>Made to be <em>known closely.</em></h2><p>Materials, proportions and care are generated from the current Maison record.</p><a class="text-link" href="${link('pages/services/appointment.html')}">Request a private appointment →</a></div><div class="product-accordion"><details open><summary><span>Details &amp; composition</span><span aria-hidden="true">+</span></summary><div class="product-accordion-body"><ul>${details}</ul><dl><div><dt>Composition</dt><dd>${esc(p.composition)}</dd></div><div><dt>Origin</dt><dd>${esc(p.origin)}</dd></div></dl></div></details><details><summary><span>Size &amp; fit</span><span aria-hidden="true">+</span></summary><div class="product-accordion-body"><p>${esc(p.fit)}</p><p>For personal sizing advice, our client advisors are available through a private appointment.</p></div></details><details><summary><span>Care &amp; services</span><span aria-hidden="true">+</span></summary><div class="product-accordion-body"><p>${esc(p.care)}</p><p>Every piece is delivered in protective Maison packaging with material-specific care guidance.</p></div></details></div></div></section><section class="section dark product-signature"><div class="wrap"><p class="eyebrow">MAISON CRAFT · ${esc(p.reference)}</p><p class="quote">Made with patience, to become more personal with time.</p></div></section>`
  }
  const views={home, 'new-in':newIn, collections, shop, journal, about:maison, services, shows, 'show-aw26':showDetail, 'artistic-looks':artisticLooks, heritage, 'maison-codes':maisonCodes, nocturne, salon, making, 'materials-lab':materialsLab, clothing:catalogue, accessories:catalogue, coats:catalogue,bags:catalogue,scarves:catalogue,jewellery:catalogue,atelier:article,materials:article,appointment,shipping,wishlist:account,cart:account,'sign-in':account,checkout,product:detail};
  const initialTransition=isCategoryPage?categoryTransition():hasIncomingShopMaterial?categoryTransition(incomingShopMaterial):isImmersivePage?immersiveTransition():page==='home'&&!skipEntry?homeTransition():page!=='home'&&!skipEntry?standardTransition():'';
  document.body.insertAdjacentHTML('afterbegin',`${initialTransition}<div class="ambient-bg" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div class="cursor-aura" aria-hidden="true"></div>`); $('#site-shell').innerHTML=header(); $('#content').innerHTML=(views[page]||home)(); document.body.insertAdjacentHTML('beforeend',footer());
  if(document.documentElement.classList.contains('transition-pending'))requestAnimationFrame(()=>{document.documentElement.classList.remove('transition-pending');delete document.documentElement.dataset.transitionHold});
  function renderSaved(){const el=$('.saved-grid');if(!el)return;const ps=app.products.filter(p=>wish.includes(p.id));el.innerHTML=ps.length?ps.map(product).join(''):`<p class="empty">Your saved edit is waiting for its first piece.</p>`}
  function renderCart(){const list=$('.cart-list'),sum=$('.cart-summary');if(!list)return;const ps=cart.map(id=>app.products.find(p=>p.id===id)).filter(Boolean),total=ps.reduce((a,p)=>a+p.price,0);list.innerHTML=ps.length?ps.map((p,i)=>`<div class="cart-row${Number(p.stock)>0?'':' is-unavailable'}"><a href="${productLink(p)}" aria-label="View ${esc(p.name)}"><img src="${R}images/${esc(p.image)}" alt="${esc(p.name)}"></a><div><h3><a href="${productLink(p)}">${esc(p.name)}</a></h3><p>${esc(p.colour)}</p><small class="product-stock" data-state="${Number(p.stock)>0?'available':'unavailable'}">${Number(p.stock)>0?`${p.stock} available`:'Unavailable'}</small><button class="button remove" data-index="${i}">Remove</button></div><span class="price">${fmt(p.price)}</span></div>`).join(''):`<p class="empty">Your bag is empty. Start with a considered piece.</p>`;sum.innerHTML=`<div><span>Subtotal</span><span>${fmt(total)}</span></div><div><span>Inventory</span><span>${catalogueDataSource==='live'?'Live database':'Preview mode'}</span></div><div><span>Delivery</span><span>Complimentary</span></div><div class="total"><span>Total</span><span>${fmt(total)}</span></div><a class="button wine" href="${link('pages/checkout.html')}">Checkout</a>`}
